// ===========================================================================
// 3. ENCODING PRESERVATION: hand-craft non-canonical registration CBOR and
//    check from_metadata_bytes -> to_metadata_bytes.
// ===========================================================================

/// Write a weighted delegation-distribution array: `[ [voting_key, weight] ]`.
fn craft_delegation(ser: &mut Serializer, deleg_indef: bool) {
    if deleg_indef {
        ser.write_array(Len::Indefinite).unwrap();
    } else {
        ser.write_array(Len::Len(1)).unwrap();
    }
    ser.write_array(Len::Len(2)).unwrap();
    ser.write_bytes(VOTING_KEY_BYTES).unwrap();
    ser.write_unsigned_integer(1).unwrap();
    if deleg_indef {
        ser.write_special(Special::Break).unwrap();
    }
}

/// Write the inner CIP36_key_registration map (5 fields incl voting_purpose 0).
fn craft_key_registration(ser: &mut Serializer, inner_indef: bool, oversized_nonce: bool) {
    if inner_indef {
        ser.write_map(Len::Indefinite).unwrap();
    } else {
        ser.write_map(Len::Len(5)).unwrap();
    }
    ser.write_unsigned_integer(1).unwrap();
    craft_delegation(ser, false);
    ser.write_unsigned_integer(2).unwrap();
    ser.write_bytes(STAKE_CRED_BYTES).unwrap();
    ser.write_unsigned_integer(3).unwrap();
    ser.write_bytes(NEW_ADDRESS_BYTES).unwrap();
    ser.write_unsigned_integer(4).unwrap();
    if oversized_nonce {
        ser.write_unsigned_integer_sz(NONCE, Sz::Eight).unwrap();
    } else {
        ser.write_unsigned_integer(NONCE).unwrap();
    }
    ser.write_unsigned_integer(5).unwrap();
    ser.write_unsigned_integer(0).unwrap();
    if inner_indef {
        ser.write_special(Special::Break).unwrap();
    }
}

fn craft_witness(ser: &mut Serializer) {
    ser.write_map(Len::Len(1)).unwrap();
    ser.write_unsigned_integer(1).unwrap();
    ser.write_bytes(vec![0u8; 64]).unwrap();
}

/// Craft a full registration metadata map. `outer_indef` makes the outer map indefinite,
/// `oversized_label` writes the 61284 label as an 8-byte uint.
fn craft_registration(
    outer_indef: bool,
    oversized_label: bool,
    inner_indef: bool,
    oversized_nonce: bool,
    deleg_indef: bool,
) -> Vec<u8> {
    let mut ser = Serializer::new_vec();
    if outer_indef {
        ser.write_map(Len::Indefinite).unwrap();
    } else {
        ser.write_map(Len::Len(2)).unwrap();
    }
    if oversized_label {
        ser.write_unsigned_integer_sz(61284, Sz::Eight).unwrap();
    } else {
        ser.write_unsigned_integer(61284).unwrap();
    }
    // when the caller wants a non-canonical delegation array, thread it through the inner map
    if deleg_indef {
        // inline a key_registration that uses an indefinite delegation array
        ser.write_map(Len::Len(5)).unwrap();
        ser.write_unsigned_integer(1).unwrap();
        craft_delegation(&mut ser, true);
        ser.write_unsigned_integer(2).unwrap();
        ser.write_bytes(STAKE_CRED_BYTES).unwrap();
        ser.write_unsigned_integer(3).unwrap();
        ser.write_bytes(NEW_ADDRESS_BYTES).unwrap();
        ser.write_unsigned_integer(4).unwrap();
        ser.write_unsigned_integer(NONCE).unwrap();
        ser.write_unsigned_integer(5).unwrap();
        ser.write_unsigned_integer(0).unwrap();
    } else {
        craft_key_registration(&mut ser, inner_indef, oversized_nonce);
    }
    ser.write_unsigned_integer(61285).unwrap();
    craft_witness(&mut ser);
    if outer_indef {
        ser.write_special(Special::Break).unwrap();
    }
    ser.finalize()
}

/// Preserved case: current behavior keeps these bytes byte-for-byte.
fn assert_preserved(crafted: &[u8]) {
    let parsed = CIP36RegistrationCbor::from_metadata_bytes(crafted).unwrap();
    assert_eq!(
        hex::encode(parsed.to_metadata_bytes()),
        hex::encode(crafted),
        "expected byte-identical preservation"
    );
}

#[test]
fn preserve_inner_indefinite_map() {
    // Indefinite-length inner key_registration map is preserved (len_encoding is tracked).
    let crafted = craft_registration(false, false, true, false, false);
    assert_preserved(&crafted);
}

#[test]
fn preserve_oversized_nonce() {
    // An oversized (8-byte) inner nonce uint is preserved (nonce_encoding stores the Sz).
    let crafted = craft_registration(false, false, false, true, false);
    assert_preserved(&crafted);
}

#[test]
fn preserve_indefinite_delegation_array() {
    // Indefinite-length delegation array is preserved (weighted_encoding is tracked).
    let crafted = craft_registration(false, false, false, false, true);
    assert_preserved(&crafted);
}

#[test]
fn preserve_outer_indefinite_map() {
    // The OUTER metadata map's length encoding is tracked by the generated type (the
    // codegen migration gave the view types their own outer encodings): an indefinite outer
    // map round-trips byte-exactly.
    let crafted = craft_registration(true, false, false, false, false);
    assert_preserved(&crafted);
}

#[test]
fn preserve_oversized_outer_label() {
    // The outer 61284/61285 label key encodings are now tracked: an oversized (8-byte) label
    // round-trips byte-exactly.
    let crafted = craft_registration(false, true, false, false, false);
    assert_preserved(&crafted);
}

// ===========================================================================
// 4. Canonical serialization goldens (force_canonical normalizes non-canonical
//    inner bytes).
// ===========================================================================

/// Craft a standalone (non-metadata-wrapped) non-canonical inner key_registration:
/// indefinite map + oversized nonce.
fn craft_inner_key_registration_noncanonical() -> Vec<u8> {
    let mut ser = Serializer::new_vec();
    craft_key_registration(&mut ser, true, true);
    ser.finalize()
}

/// Craft a standalone non-canonical inner key_deregistration: indefinite map + oversized nonce
/// + explicit voting_purpose 0.
fn craft_inner_key_deregistration_noncanonical() -> Vec<u8> {
    let mut ser = Serializer::new_vec();
    ser.write_map(Len::Indefinite).unwrap();
    ser.write_unsigned_integer(1).unwrap();
    ser.write_bytes(STAKE_CRED_BYTES).unwrap();
    ser.write_unsigned_integer(2).unwrap();
    ser.write_unsigned_integer_sz(NONCE, Sz::Eight).unwrap();
    ser.write_unsigned_integer(3).unwrap();
    ser.write_unsigned_integer(0).unwrap();
    ser.write_special(Special::Break).unwrap();
    ser.finalize()
}

const CANONICAL_KEY_REG: &str = "a501818258200036ef3e1f0d3f5989e2d155ea54bdb2a72c4c456ccb959af4c94868f473f5a001025820e3cd2404c84de65f96918f18d5b445bcb933a7cda18eeded7945dd191e432369035839004777561e7d9ec112ec307572faec1aff61ff0cfed68df4cd5c847f1872b617657881e30ad17c46e4010c9cb3ebb2440653a34d32219c83e9041904d20500";
const CANONICAL_KEY_DEREG: &str =
    "a3015820e3cd2404c84de65f96918f18d5b445bcb933a7cda18eeded7945dd191e432369021904d20300";

#[test]
fn canonical_key_registration() {
    let noncanon = craft_inner_key_registration_noncanonical();
    let parsed = CIP36KeyRegistration::from_cbor_bytes(&noncanon).unwrap();
    // non-canonical (indefinite map + oversized nonce) encoding is preserved on to_cbor_bytes ...
    assert_eq!(
        hex::encode(parsed.to_cbor_bytes()),
        hex::encode(&noncanon),
        "non-canonical encoding should be preserved by to_cbor_bytes"
    );
    // ... but force_canonical normalizes it to the golden.
    assert_ne!(
        hex::encode(parsed.to_canonical_cbor_bytes()),
        hex::encode(&noncanon),
        "canonical form should differ from the non-canonical input"
    );
    assert_eq!(
        hex::encode(parsed.to_canonical_cbor_bytes()),
        CANONICAL_KEY_REG
    );
}

#[test]
fn canonical_key_deregistration() {
    let noncanon = craft_inner_key_deregistration_noncanonical();
    let parsed = CIP36KeyDeregistration::from_cbor_bytes(&noncanon).unwrap();
    assert_eq!(
        hex::encode(parsed.to_cbor_bytes()),
        hex::encode(&noncanon),
        "non-canonical encoding should be preserved by to_cbor_bytes"
    );
    assert_ne!(
        hex::encode(parsed.to_canonical_cbor_bytes()),
        hex::encode(&noncanon),
        "canonical form should differ from the non-canonical input"
    );
    assert_eq!(
        hex::encode(parsed.to_canonical_cbor_bytes()),
        CANONICAL_KEY_DEREG
    );
}

// ===========================================================================
// 6. OFFICIAL CIP-36 test vectors (from the CIP-0036 spec test vector).
//    See scratchpad/cip36-test-vector.md. These are the highest-value goldens:
//    real on-chain-shaped bytes with real Ed25519 witness signatures.
// ===========================================================================

// Raw CIP36_key_registration map bodies (the value under label 61284), verbatim from the spec.
const OFFICIAL_LEGACY_KEYREG: &str = "a40158200036ef3e1f0d3f5989e2d155ea54bdb2a72c4c456ccb959af4c94868f473f5a0025820e3cd2404c84de65f96918f18d5b445bcb933a7cda18eeded7945dd191e43236903581de072b617657881e30ad17c46e4010c9cb3ebb2440653a34d32219c83e9041904d2";
const OFFICIAL_CIP36_KEYREG: &str = "a501818258200036ef3e1f0d3f5989e2d155ea54bdb2a72c4c456ccb959af4c94868f473f5a001025820e3cd2404c84de65f96918f18d5b445bcb933a7cda18eeded7945dd191e432369035839004777561e7d9ec112ec307572faec1aff61ff0cfed68df4cd5c847f1872b617657881e30ad17c46e4010c9cb3ebb2440653a34d32219c83e9041904d20500";

// Real Ed25519 witness signatures (the value under key 1 of label 61285).
const OFFICIAL_SIG_LEGACY: &str = "a9ec8735804c6c4c5c4a02e9589c65508ec7060063b2d7dbeba82d1cbfa1b8be6b457f95d4ead5e8b454b989624fa44e0b89a64d089fdc0a6a1268fef4876d0f";
const OFFICIAL_SIG_CIP36: &str = "cbb96ba1596fafc18eec84e306feea3067ba1c6ace95b11af820bcbd53837ef32bdcf28176749061e1f2a1300d4df98c80582722786e40cf330072d0b78a7408";

#[test]
fn official_inner_key_registration_roundtrip() {
    // from_cbor_bytes(official body) -> to_cbor_bytes is byte-identical.
    inner_roundtrip::<CIP36KeyRegistration>(OFFICIAL_LEGACY_KEYREG);
    inner_roundtrip::<CIP36KeyRegistration>(OFFICIAL_CIP36_KEYREG);
}

#[test]
fn official_struct_built_matches_vector() {
    // A struct built from the vector's own field values re-serializes to the official bytes.
    // Legacy: 4-field body, no voting_purpose.
    let legacy = legacy_registration();
    assert_eq!(
        hex::encode(legacy.key_registration.to_cbor_bytes()),
        OFFICIAL_LEGACY_KEYREG,
        "legacy struct -> bytes must equal official vector"
    );
    // CIP-36: 5-field body ending `0500` (voting_purpose 0 EXPLICIT on the wire even though the
    // CDDL marks it `.default 0`). The freshly-built weighted registration reproduces this.
    let cip36 = weighted_registration(0);
    assert_eq!(
        hex::encode(cip36.key_registration.to_cbor_bytes()),
        OFFICIAL_CIP36_KEYREG,
        "cip36 struct -> bytes must equal official vector"
    );
}

#[test]
fn official_full_metadata_roundtrip() {
    // Construct the full official metadata CBOR: {61284: key_reg, 61285: {1: sig}}.
    // a2 = map(2); 19ef64 = 61284; 19ef65 = 61285; a10158 40 = {1: bytes(64)}.
    let legacy_meta = format!(
        "a219ef64{}19ef65a1015840{}",
        OFFICIAL_LEGACY_KEYREG, OFFICIAL_SIG_LEGACY
    );
    let cip36_meta = format!(
        "a219ef64{}19ef65a1015840{}",
        OFFICIAL_CIP36_KEYREG, OFFICIAL_SIG_CIP36
    );
    for meta_hex in [&legacy_meta, &cip36_meta] {
        let bytes = hex::decode(meta_hex).unwrap();
        let parsed = CIP36RegistrationCbor::from_metadata_bytes(&bytes).unwrap();
        assert_eq!(
            hex::encode(parsed.to_metadata_bytes()),
            *meta_hex,
            "official metadata round-trip not byte-identical"
        );
    }
}

// ===========================================================================
// 5. TryFrom<&Metadata> / TryInto<Metadata> round-trip.
// ===========================================================================

#[test]
fn registration_metadata_conversion() {
    use std::convert::TryInto;
    let reg = weighted_registration(1);
    let metadata: Metadata = (&reg).try_into().unwrap();

    // The 61284/61285 metadatum bytes must equal the inner types' to_cbor_bytes.
    let reg_meta = metadata.get(61284).unwrap();
    assert_eq!(
        hex::encode(reg_meta.to_cbor_bytes()),
        hex::encode(reg.key_registration.to_cbor_bytes())
    );
    let wit_meta = metadata.get(61285).unwrap();
    assert_eq!(
        hex::encode(wit_meta.to_cbor_bytes()),
        hex::encode(reg.registration_witness.to_cbor_bytes())
    );

    // TryFrom<&Metadata> reconstructs an equivalent view.
    let back = CIP36RegistrationCbor::try_from(&metadata).unwrap();
    assert_eq!(
        hex::encode(back.to_metadata_bytes()),
        hex::encode(reg.to_metadata_bytes())
    );
}

#[test]
fn deregistration_metadata_conversion() {
    use std::convert::TryInto;
    let dereg = deregistration(1);
    let metadata: Metadata = (&dereg).try_into().unwrap();

    let dereg_meta = metadata.get(61286).unwrap();
    assert_eq!(
        hex::encode(dereg_meta.to_cbor_bytes()),
        hex::encode(dereg.key_deregistration.to_cbor_bytes())
    );
    let wit_meta = metadata.get(61285).unwrap();
    assert_eq!(
        hex::encode(wit_meta.to_cbor_bytes()),
        hex::encode(dereg.deregistration_witness.to_cbor_bytes())
    );

    let back = CIP36DeregistrationCbor::try_from(&metadata).unwrap();
    assert_eq!(
        hex::encode(back.to_metadata_bytes()),
        hex::encode(dereg.to_metadata_bytes())
    );
}

